/// <summary>
///    AVA <c>initValue</c> method.
/// </summary>
public void initValue()
{
    super();

    this.Selected = NoYes::Yes;
}

/// <summary>
///    AVA <c>initValueFromCustTable</c> method.
/// </summary>
/// <param name="_custTable">
///    <c>CustTable</c> as type
/// </param>
public void initValueFromCustTable(CustTable _custTable)
{
    AVAPriceIncreaseTable   locAVAPriceIncreaseTable;
    CustInvoiceJour         locCustInvoiceJour;

    if(this.PriceIncreaseSet)
    {
        locAVAPriceIncreaseTable = this.priceIncreaseTable();
    }

    this.CustAccountNum = _custTable.AccountNum;
    if(locAVAPriceIncreaseTable.RecId && this.CustAccountNum)
    {
        this.ChainId            = _custTable.CompanyChainId;

        select sum(InvoiceAmount), sum(InvoiceAmountMST)
        from    locCustInvoiceJour
        where   locCustInvoiceJour.InvoiceAccount   == this.CustAccountNum
            &&  locCustInvoiceJour.InvoiceDate      >= locAVAPriceIncreaseTable.SalesEvaluationStart;
        this.InvoiceAmount      = locCustInvoiceJour.InvoiceAmount;
        this.InvoiceAmountMST   = locCustInvoiceJour.InvoiceAmountMST;
    }
}

/// <summary>
///    AVA <c>initValueFromAVAPriceIncreaseTable</c> method.
/// </summary>
/// <param name="_priceIncreaseTable">
///    <c>AVAPriceIncreaseTable</c> as type
/// </param>
public void initValueFromAVAPriceIncreaseTable(AVAPriceIncreaseTable _priceIncreaseTable)
{
    this.PriceIncreaseSet = _priceIncreaseTable.PriceIncreaseSet;
}

/// <summary>
///    Finds the specified record in the <c>AVAPriceIncreaseCustomersTable</c> table.
/// </summary>
/// <param name="_recordId">
///    The record ID of the <c>AVAPriceIncreaseCustomersTable</c> record to find.
/// </param>
/// <param name="_recordId2">
///    The record ID of the <c>AVAPriceIncreaseCustomersTable</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>AVAPriceIncreaseCustomersTable</c> table; otherwise, an empty record.
/// </returns>
public static AVAPriceIncreaseCustomersTable find(  AVAPriceIncreaseSet _recordId,
                                                    CustAccount         _recordId2,
                                                    boolean             _forUpdate = false)
{
    AVAPriceIncreaseCustomersTable record;

    if (    _recordId 
        &&  _recordId2  )
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        index hint AVAPriceIncreaseCustomersTableIdx
        where   record.PriceIncreaseSet   == _recordId 
            &&  record.CustAccountNum   == _recordId;
    }
    return record;
}

/// <summary>
///    Finds the specified record in the <c>AVAPriceIncreaseCustomersTable</c> table.
/// </summary>
/// <param name="_recordId">
///    The record ID of the <c>AVAPriceIncreaseCustomersTable</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>AVAPriceIncreaseCustomersTable</c> table; otherwise, an empty record.
/// </returns>
public static AVAPriceIncreaseCustomersTable findByRecId(RecId _recordId, boolean _forUpdate = false)
{
    AVAPriceIncreaseCustomersTable record;

    if (_recordId)
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        where record.RecId == _recordId;
    }
    return record;
}

/// <summary>
///    AVA <c>modifiedField</c> method.
/// </summary>
/// <param name="_fieldId">
///    <c>FieldId</c> as type
/// </param>
public void modifiedField(FieldId _fieldId)
{
    switch(_fieldId)
    {
        case fieldNum(AVAPriceIncreaseCustomersTable, CustAccountNum):
            if(this.CustAccountNum != '')
            {
                this.CustAccountNum = this.CustAccountNum;
            }
            break;

        case fieldNum(AVAPriceIncreaseCustomersTable, ChainId):
            if(this.ChainId != '')
            {
                this.ChainId = this.ChainId;
            }
            break;

        default :
            break;
    }
    super(_fieldId);
}

/// <summary>
///    AVA <c>addMissingCustomerLines</c> method.
/// </summary>
public static void deleteCustomerLines( AVAPriceIncreaseSet _avaPriceIncreaseSet, 
                                        CustAccount         _custAccount = ''       )
{
    AVAPriceIncreaseTable           locAVAPriceIncreaseTable;
    AVAPriceIncreaseCustomersTable  locAVAPriceIncreaseCustomersTable;

    locAVAPriceIncreaseTable = AVAPriceIncreaseTable::find(_avaPriceIncreaseSet);

    if(locAVAPriceIncreaseTable.RecId)
    {
        ttsbegin;
        if(_custAccount)
        {
            locAVAPriceIncreaseCustomersTable = AVAPriceIncreaseCustomersTable::find(   _avaPriceIncreaseSet, 
                                                                                        _custAccount            );
            if(locAVAPriceIncreaseCustomersTable.RecId)
            {
                locAVAPriceIncreaseCustomersTable.delete();
            }
        }
        else
        {
            delete_from locAVAPriceIncreaseCustomersTable
            where locAVAPriceIncreaseCustomersTable.PriceIncreaseSet == _avaPriceIncreaseSet;
        }
        ttscommit;
    }
}

 /// <summary>
 ///    AVA <c>addFromAVAPriceIncreaseTable</c> method.
 /// </summary>
 /// <param name="_record">
 ///     <c>AVAPriceIncreaseTable</c> as type
 /// </param>
 /// <returns>
 ///     <c>boolean</c> as return value
 /// </returns>
public boolean addFromAVAPriceIncreaseTable(AVAPriceIncreaseTable _record)
 {
     boolean retVal;

     date                            locToday;
     utcDateTime                     locTodayDateTime;
     utcDateTime                     locTodayDateTimeNull;

     AVAPriceIncreaseTable           locAVAPriceIncreaseTable;
     AVAPriceIncreaseCustomersTable  locAVAPriceIncreaseCustomersTable;
     AVAPriceIncreaseCustomersTable  locAVAPICTNotExists;
     CustTable                       locCustTable;
     Set                             locPriceDiscGroupsDefinedSet;
     boolean                         locPriceDiscGroupMatch;
     AVAPriceIncreasePriceDiscGroup  locAVAPriceIncreasePriceDiscGroup;
     smmBusRelChainGroup             locsmmBusRelChainGroup;
     PriceDiscGroup                  locPriceDiscGroupBusRelChain;
     PriceGroupId                    locPriceGroupIdCust;
     PriceGroupId                    locPriceGroupIdCust1;
     PriceGroupId                    locPriceGroupIdCust2;
     PriceGroupId                    locPriceGroupIdBusRelChain;
     PriceGroupId                    locPriceGroupIdBusRelChain1;
     PriceGroupId                    locPriceGroupIdBusRelChain2;
     smmBusRelTable                  locsmmBusRelTableBusRelChain;
     smmBusRelAccount                locsmmBusRelAccountChain;

     AVASalesParameters              locAVASalesParameters;
     DirRelationshipTypeId           locDirRelationshipTypeIdInfo;
     DirRelationshipTypeId           locDirRelationshipTypeIdData;
     DirPartyRelationship            locDirPartyRelationship;

     AVAContactPersonIdPriceInfoCust  locAVAContactPersonIdPriceInfoCust;
     AVAContactPersonIdPriceDataCust  locAVAContactPersonIdPriceDataCust;
     AVAContactPersonIdPriceInfoChain locAVAContactPersonIdPriceInfoChain;
     AVAContactPersonIdPriceDataChain locAVAContactPersonIdPriceDataChain;

     retVal                      = true;
     locAVAPriceIncreaseTable    = _record;
     locToday                    = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
     locTodayDateTime            = DateTimeUtil::newDateTime(locToday, 0);
     locTodayDateTimeNull        = DateTimeUtil::newDateTime(dateNull(), 0);

     void insertAVAPriceIncreaseLine(CustTable _custTable)
     {
         ttsbegin;
         locAVAPriceIncreaseCustomersTable.clear();
         locAVAPriceIncreaseCustomersTable.initValue();
         locAVAPriceIncreaseCustomersTable.initValueFromAVAPriceIncreaseTable(locAVAPriceIncreaseTable);
         locAVAPriceIncreaseCustomersTable.initValueFromCustTable(_custTable);
         locAVAPriceIncreaseCustomersTable.BusRelAccountChain            = locsmmBusRelAccountChain;
         locAVAPriceIncreaseCustomersTable.ContactPersonIdPriceInfoCust  = locAVAContactPersonIdPriceInfoCust;
         locAVAPriceIncreaseCustomersTable.ContactPersonIdPriceDataCust  = locAVAContactPersonIdPriceDataCust;
         locAVAPriceIncreaseCustomersTable.ContactPersonIdPriceInfoChain = locAVAContactPersonIdPriceInfoChain;
         locAVAPriceIncreaseCustomersTable.ContactPersonIdPriceDataChain = locAVAContactPersonIdPriceDataChain;

         if (locAVAPriceIncreaseCustomersTable.validateWrite())
         {
             locAVAPriceIncreaseCustomersTable.write();
         }
         ttscommit;
     }

     void initLocals()
     {
         locPriceDiscGroupMatch              = false;

         locPriceGroupIdCust                 = '';
         locPriceGroupIdCust1                = '';
         locPriceGroupIdCust2                = '';
         locPriceGroupIdBusRelChain          = '';
         locPriceGroupIdBusRelChain1         = '';
         locPriceGroupIdBusRelChain2         = '';
         locPriceDiscGroupBusRelChain        = null;
         locsmmBusRelAccountChain            = '';
         locAVAContactPersonIdPriceInfoCust  = '';
         locAVAContactPersonIdPriceDataCust  = '';
         locAVAContactPersonIdPriceInfoChain = '';
         locAVAContactPersonIdPriceDataChain = '';
     }

     if(locAVAPriceIncreaseTable.PriceIncreaseSet)
     {
         locPriceDiscGroupsDefinedSet = new Set(Types::String);
         locPriceDiscGroupsDefinedSet = locAVAPriceIncreaseTable.getPriceDiscGroupSetDefined();

         if (!locPriceDiscGroupsDefinedSet.empty())
         {
             locAVASalesParameters           = AVASalesParameters::find();
             locDirRelationshipTypeIdInfo    = locAVASalesParameters.RelationshipTypeIdPriceInfo;
             locDirRelationshipTypeIdData    = locAVASalesParameters.RelationshipTypeIdPriceFile;

             AVAPriceIncreaseCustomersTable::deleteCustomerLines(locAVAPriceIncreaseTable.PriceIncreaseSet);

             while select locCustTable
             where   locCustTable.AVANetPG1      != ''
                 ||  locCustTable.AVANetPG2      != ''
                 //||  locCustTable.PriceGroup     != ''
                 ||  locCustTable.CompanyChainId != ''
                 notexists join locAVAPICTNotExists
                 where   locAVAPICTNotExists.PriceIncreaseSet    == locAVAPriceIncreaseTable.PriceIncreaseSet
                     &&  locAVAPICTNotExists.CustAccountNum      == locCustTable.AccountNum
             {
                 initLocals();

                 if(locCustTable.AVANetPG1)
                 {
                     if(locPriceDiscGroupsDefinedSet.in(locCustTable.AVANetPG1))
                     {
                         locPriceDiscGroupMatch  = true;
                         locPriceGroupIdCust     = locCustTable.AVANetPG1;
                         locPriceGroupIdCust1    = locCustTable.AVANetPG1;
                     }
                 }
                 if(locCustTable.AVANetPG2)
                 {
                     if(locPriceDiscGroupsDefinedSet.in(locCustTable.AVANetPG2))
                     {
                         locPriceDiscGroupMatch  = true;
                         locPriceGroupIdCust     = locCustTable.AVANetPG2;
                         locPriceGroupIdCust2    = locCustTable.AVANetPG2;
                     }
                 }
                 else if(locCustTable.CompanyChainId)
                 {
                     select firstonly locsmmBusRelChainGroup
                     where locsmmBusRelChainGroup.ChainId == locCustTable.CompanyChainId;

                     if(locsmmBusRelChainGroup.AVANetPG1)
                     {
                         if(locPriceDiscGroupsDefinedSet.in(locsmmBusRelChainGroup.AVANetPG1))
                         {
                             locPriceDiscGroupMatch      = true;
                             locPriceGroupIdBusRelChain  = locsmmBusRelChainGroup.AVANetPG1;
                             locPriceGroupIdBusRelChain1 = locsmmBusRelChainGroup.AVANetPG1;
                         }
                     }
                     if(locsmmBusRelChainGroup.AVANetPG2)
                     {
                         if(locPriceDiscGroupsDefinedSet.in(locsmmBusRelChainGroup.AVANetPG2))
                         {
                             locPriceDiscGroupMatch      = true;
                             locPriceGroupIdBusRelChain  = locsmmBusRelChainGroup.AVANetPG2;
                             locPriceGroupIdBusRelChain2 = locsmmBusRelChainGroup.AVANetPG2;
                         }
                     }
                 }

                 if(locPriceDiscGroupMatch)
                 {
                     select firstonly1 validTimeState(locTodayDateTime) *
                     from    locDirPartyRelationship
                     where   locDirPartyRelationship.ParentParty         == locCustTable.Party
                         &&  locDirPartyRelationship.RelationshipTypeId  == locDirRelationshipTypeIdInfo;
                         /*
                         &&  locDirPartyRelationship.ValidFrom           <= locTodayDateTime
                         &&  locDirPartyRelationship.ValidTo             >= locTodayDateTime; 
                         */
                     if(locDirPartyRelationship.RecId)
                     {
                         locAVAContactPersonIdPriceInfoCust = ContactPerson::findByPartyRecId(locDirPartyRelationship.ChildParty).ContactPersonId;
                     }

                     select firstonly1 validTimeState(locTodayDateTime) *
                     from    locDirPartyRelationship
                     where   locDirPartyRelationship.ParentParty         == locCustTable.Party
                         &&  locDirPartyRelationship.RelationshipTypeId  == locDirRelationshipTypeIdData;
                         /*
                         &&  locDirPartyRelationship.ValidFrom           <= locTodayDateTime
                         &&  locDirPartyRelationship.ValidTo             >= locTodayDateTime;
                         */
                     if(locDirPartyRelationship.RecId)
                     {
                         locAVAContactPersonIdPriceDataCust = ContactPerson::findByPartyRecId(locDirPartyRelationship.ChildParty).ContactPersonId;
                     }

                     if(locPriceGroupIdBusRelChain)
                     {
                         locPriceDiscGroupBusRelChain = PriceDiscGroup::find(ModuleInventCustVend::Cust,
                                                                             PriceGroupType::PriceGroup,
                                                                             locPriceGroupIdBusRelChain);
                         if(     locPriceDiscGroupBusRelChain.RecId
                             &&  locPriceDiscGroupBusRelChain.NDX_BusRelAccount
                             &&  !locPriceDiscGroupBusRelChain.NDX_Blocked        )
                         {
                             locsmmBusRelTableBusRelChain    = smmBusRelTable::find(locPriceDiscGroupBusRelChain.NDX_BusRelAccount);
                             if(locsmmBusRelTableBusRelChain.Recid)
                             {
                                 locsmmBusRelAccountChain = locsmmBusRelTableBusRelChain.BusRelAccount;

                                 select firstonly1 validTimeState(locTodayDateTime) *
                                 from    locDirPartyRelationship
                                 where   locDirPartyRelationship.ParentParty         == locsmmBusRelTableBusRelChain.Party
                                     &&  locDirPartyRelationship.RelationshipTypeId  == locDirRelationshipTypeIdInfo;
                                 /*
                                 &&  locDirPartyRelationship.ValidFrom           <= locTodayDateTime
                                 &&  locDirPartyRelationship.ValidTo             >= locTodayDateTime;
                                 */
                                 if(locDirPartyRelationship.RecId)
                                 {
                                     locAVAContactPersonIdPriceInfoChain = ContactPerson::findByPartyRecId(locDirPartyRelationship.ChildParty).ContactPersonId;
                                 }

                                 select firstonly1 validTimeState(locTodayDateTime) *
                                 from    locDirPartyRelationship
                                 where   locDirPartyRelationship.ParentParty         == locsmmBusRelTableBusRelChain.Party
                                     &&  locDirPartyRelationship.RelationshipTypeId  == locDirRelationshipTypeIdData;
                                 /*
                                 &&  locDirPartyRelationship.ValidFrom           <= locTodayDateTime
                                 &&  locDirPartyRelationship.ValidTo             >= locTodayDateTime;
                                 */
                                 if(locDirPartyRelationship.RecId)
                                 {
                                     locAVAContactPersonIdPriceDataChain = ContactPerson::findByPartyRecId(locDirPartyRelationship.ChildParty).ContactPersonId;
                                 }
                             }
                         }
                     }

                     insertAVAPriceIncreaseLine(locCustTable);
                 }
             }
         }
     }
     return retVal;
 }

/// <summary>
///     AVA <c>getPriceDiscGroupsSetDefined</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public Set getPriceDiscGroupsSetDefined(AVAPriceIncreaseSet _priceIncreaseSet)
{
    Set                             locPriceDiscGroupsDefined;
    AVAPriceIncreasePriceDiscGroup  locAVAPriceIncreasePriceDiscGroup;

    locPriceDiscGroupsDefined = new Set(Types::Int64);

    while select locAVAPriceIncreasePriceDiscGroup
    where   locAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet == _priceIncreaseSet
    {
        locPriceDiscGroupsDefined.add(locAVAPriceIncreasePriceDiscGroup.RecId);
    }

    return locPriceDiscGroupsDefined;
}

/// <summary>
///     AVA <c>priceIncreaseTable</c> method.
/// </summary>
/// <param name="_forUpdate">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>AVAPriceIncreaseTable</c> as return value
/// </returns>
public AVAPriceIncreaseTable priceIncreaseTable(boolean _forUpdate = false)
{
    AVAPriceIncreaseTable retVal;

    retVal = AVAPriceIncreaseTable::find(this.PriceIncreaseSet);

    return retVal;
}
